DROP TABLE IF EXISTS `vw_productos_stock_bajo_activos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_productos_stock_bajo_activos` AS select `p`.`id` AS `id`,`p`.`sku` AS `sku`,`p`.`nombre` AS `nombre`,`p`.`stock` AS `stock`,`p`.`min_stock` AS `min_stock`,`p`.`costo_ultimo` AS `costo_ultimo`,`p`.`proveedor_id` AS `proveedor_default_id`,`prov`.`nombre` AS `proveedor_default_nombre`,case when `p`.`stock` = 0 then 'agotado' when `p`.`stock` <= `p`.`min_stock` then 'bajo' else 'normal' end AS `nivel_stock`,`p`.`min_stock` - `p`.`stock` AS `cantidad_faltante` from (`productos` `p` left join `proveedores` `prov` on(`prov`.`id` = `p`.`proveedor_id`)) where `p`.`estado` <> 'inactivo' and `p`.`stock` <= `p`.`min_stock` order by case when `p`.`stock` = 0 then 0 else 1 end,`p`.`min_stock` - `p`.`stock` desc 
;

